'use client';
import {WorkExceptions} from './staff-oversight';
import {StaffPerformance} from './staff-performance';
import type {RecordRow} from './ui';
import {useCallback,useEffect,useRef,useState,type FormEvent} from 'react';
import {ArrowLeft,ArrowRight,CalendarDays,CheckCircle2,Clock3,Coffee,Download,FileCheck2,ListChecks,LogIn,LogOut,Plus,RefreshCw,ShieldCheck,Users,X} from 'lucide-react';
import type {Viewer} from './workspace';
import type {WorkPolicy,BreakOption,WorkBreak} from '@/lib/walshken/attendance-rules';
import type {Attendance,Shift,Sheet} from '@/lib/walshken/workforce';
import {ActionForm,dateText as originalDateText} from './ui';
const dateText=(value:string|null|undefined,time=false,zone='UTC')=>originalDateText(value,time,['America/Edmonton','Canada/Mountain'].includes(zone)&&value&&Date.parse(value)>=Date.parse('2026-11-01T00:00:00Z')?'Etc/GMT+6':zone);
type Break=WorkBreak&{id:string;kind:string;label:string};
type Entry=Attendance&{name:string;title:string|null;location:string|null;shift_start:string|null;shift_end:string|null;breaks:Break[];totals:{gross:number;unpaid:number;paid:number;breakSeconds:number};issues:string[];late:boolean;early:boolean;lateMinutes:number;earlyMinutes:number;missedClockOut:boolean;timesheet_status:string|null};
type Employee={id:string;name:string;role:string;jurisdiction:string;time_zone:string;policy:WorkPolicy|null;policyRevision:number;policyVersions?:{effective:string;revision:number}[]};
type Scheduled=Shift&{name:string;leave_conflict:number;holiday_conflict:number};
type Timesheet=Sheet&{name:string;starts_at:string;ends_at:string;review_note:string;source:string};
type Correction={id:string;requested_by:string;attendance_id:string;employee_id:string;name:string;status:string;revision:number;proposed_start:string;proposed_end:string;proposed_breaks:string;note:string;review_note:string;created_at:string};
type Leave={id:string;employee_id:string;name:string;category:string;starts_on:string;ends_on:string;status:string;revision:number;note:string;review_note:string};
type Holiday={id:string;name:string;on_date:string;type:string;cancelled_at:string|null};
type Absence={id:string;employee_id:string;name:string;title:string;starts_at:string;ends_at:string;status:string;note:string};
type Swap={id:string;requester_id:string;partner_id:string;requester:string;partner:string;source_start:string;target_start:string;status:string;revision:number;note:string;review_note:string};
type Event={id:string;name:string;actor:string;action:string;created_at:string;detail:string;entity:string};
type Report={from:string;to:string;period:string;rows:{employee:string;employeeNo:string;employeeId:string;period:string;gross:number;unpaid:number;paid:number;approved:number;openRecords:number}[];totals:{gross:number;unpaid:number;paid:number;approved:number}};
type Data={managedWorkforce:boolean;canViewPerformance?:boolean;canExportAttendance?:boolean;workExceptions?:RecordRow[]|null;leaveBalances?:{balances:{code:string;name:string;paid:boolean;entitlement:number;used:number;pending:number;available:number;from:string;to:string}[]}|null;leaveError?:string;staffReadiness?:boolean;holidayManagement?:boolean;team:boolean;manager:boolean;policyAdmin:boolean;actorId:string;from:string;to:string;today:string;serverTime:string;rows:Entry[];shifts:Scheduled[];sheets:Timesheet[];corrections:Correction[];leave:Leave[];holidays:Holiday[];absences:Absence[];staff:Employee[];swaps:Swap[];events:Event[];policy:WorkPolicy|null;policyRevision:number;policyError:string;active:(Attendance&{breaks:Break[];policy:WorkPolicy})|null;currentShifts:Shift[];swapChoices:(Shift&{name:string})[];report:Report;truncated:boolean;rules:{source:string;verifiedOn:string}};
type Review={action:string;id:string;revision?:number;title:string;choices?:string[];incidents?:string[]};
const hours=(s:number)=>`${(s/3600).toFixed(2)} h`;
const clock=(s:number)=>`${Math.floor(s/3600)}:${String(Math.floor(s/60)%60).padStart(2,'0')}:${String(Math.floor(s)%60).padStart(2,'0')}`;
const dayAdd=(s:string,n:number)=>new Date(Date.parse(s+'T12:00Z')+n*86400000).toISOString().slice(0,10);
const monthEnd=(s:string)=>new Date(Date.UTC(Number(s.slice(0,4)),Number(s.slice(5,7)),0)).toISOString().slice(0,10);
const wall=(s:string,z:string)=>{if(['America/Edmonton','Canada/Mountain'].includes(z)&&Date.parse(s)>=Date.parse('2026-11-01T00:00:00Z'))z='Etc/GMT+6';const p=new Intl.DateTimeFormat('en-CA',{timeZone:z,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(s)),v=(k:string)=>p.find(x=>x.type===k)?.value;return `${v('year')}-${v('month')}-${v('day')}T${v('hour')}:${v('minute')}`;};
async function api(action:string,data?:Record<string,unknown>,signal?:AbortSignal){const r=await fetch('/api/workforce/'+action,data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data),signal}:{cache:'no-store',signal}),body=await r.json().catch(()=>({error:'An attendance response could not be read.'}));if(!r.ok)throw Error(body.error??'Workforce request failed.');return body;}
const formValues=(event:FormEvent<HTMLFormElement>)=>Object.fromEntries(new FormData(event.currentTarget));
function Badge({children}:{children:React.ReactNode}){return <span className="wf-badge">{children}</span>;}
function Empty({text}:{text:string}){return <div className="wf-empty"><CalendarDays size={29}/><h3>No records in this view</h3><p>{text}</p></div>;}
export function WorkforceWorkspace({section,actor,initial}:{section:string;actor:Viewer;initial:unknown}){
 const [data,setData]=useState(initial as Data),[filters,setFilters]=useState({from:(initial as Data).from,to:(initial as Data).to,team:(initial as Data).team?'1':'0',period:(initial as Data).report.period}),[busy,setBusy]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState(''),[mode,setMode]=useState(''),[selected,setSelected]=useState<Entry|null>(null),[editShift,setEditShift]=useState<Scheduled|null>(null),[review,setReview]=useState<Review|null>(null),[checked,setChecked]=useState<string[]>([]),[calendar,setCalendar]=useState('month'),[tick,setTick]=useState(Date.now()),[history,setHistory]=useState<Event[]|null>(null);
 const [dateDraft,setDateDraft]=useState({from:filters.from,to:filters.to});
 const query=new URLSearchParams(filters).toString(),activeQuery=useRef(query);
 const load=useCallback(async()=>{
   try{const result=await api('list?'+query);if(activeQuery.current===query)setData(result);}
   catch(error){if(activeQuery.current===query)throw error;}
 },[query]);
 useEffect(()=>{
   activeQuery.current=query;
   const controller=new AbortController();
   api('list?'+query,undefined,controller.signal).then(result=>{
     if(!controller.signal.aborted)setData(result);
   }).catch(reason=>{
     if(!controller.signal.aborted)setError(reason.message);
   });
   return()=>controller.abort();
 },[query]);
 useEffect(()=>{const timer=setInterval(()=>{if(document.visibilityState==='visible')void load().catch(e=>setError(e.message));},20000);return()=>clearInterval(timer);},[load]);
 useEffect(()=>{const timer=setInterval(()=>setTick(Date.now()),1000);return()=>clearInterval(timer);},[]);
 async function action(name:string,input:Record<string,unknown>){setBusy(true);setError('');setNotice('');try{const result=await api(name,input);setNotice(result.message??'Saved.');setMode('');setSelected(null);setEditShift(null);setReview(null);setChecked([]);await load();return result;}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 async function showHistory(entry:Entry){setSelected(entry);setMode('history');setHistory(null);try{setHistory((await api('detail?id='+entry.id)).events);}catch(e){setError((e as Error).message);}}
 const active=data.active,pause=active?.breaks.find(b=>!b.ends_at),elapsed=active?Math.max(0,Math.floor((tick-Date.parse(active.starts_at))/1000)):0,unpaid=active?.breaks.filter(b=>!b.paid).reduce((n,b)=>n+Math.max(0,Math.floor(((b.ends_at?Date.parse(b.ends_at):tick)-Date.parse(b.starts_at))/1000)),0)??0;
 const attendance=['attendance','reports'].includes(section),scheduling=['shifts','scheduling'].includes(section),sheets=['timesheets','approvals'].includes(section),pending=data.sheets.filter(s=>s.status==='Submitted').length;
 const control=(name:string,value:string)=>{
  setError('');setChecked([]);setFilters(current=>({...current,[name]:value}));
 };
 function changeRange(from:string,to:string) {
  setError('');setChecked([]);setDateDraft({from,to});setFilters(current=>({...current,from,to}));
 }
 function navMonth(offset:number){if(calendar==='week'){const first=dayAdd(filters.from,offset*7);changeRange(first,dayAdd(first,6));return;}const date=new Date(filters.from+'T12:00Z');date.setUTCMonth(date.getUTCMonth()+offset,1);const first=date.toISOString().slice(0,10);changeRange(first,monthEnd(first));}
 const statistics=[
  {label:'Recorded payable',value:hours(data.report.totals.paid),summary:'Work minus unpaid breaks',Icon:Clock3},
  {label:'Approved hours',value:hours(data.report.totals.approved),summary:'Independently reviewed',Icon:FileCheck2},
  {label:'Unpaid breaks',value:hours(data.report.totals.unpaid),summary:'Actual recorded breaks',Icon:Coffee},
  {label:'Awaiting review',value:String(pending),summary:'Submitted timesheets',Icon:ListChecks},
 ];
 const loadingRange=data.from!==filters.from||data.to!==filters.to||data.team!==(filters.team==='1')||data.report.period!==filters.period;
 return <div className="workforce-app">
  {section==='reports'&&data.canViewPerformance&&<StaffPerformance/>}
  <div className="wf-topline"><div className="wf-segment"><button className={filters.team==='0'?'active':''} aria-pressed={filters.team==='0'} onClick={()=>control('team','0')}>My workspace</button>{data.manager&&<button className={filters.team==='1'?'active':''} aria-pressed={filters.team==='1'} onClick={()=>control('team','1')}><Users size={14}/>Team workspace</button>}</div><div className="wf-actions"><button className="btn btn-outline btn-small" onClick={()=>void load().catch(e=>setError(e.message))}><RefreshCw size={14}/>Refresh</button>{data.policyAdmin&&<button className="btn btn-outline btn-small" onClick={()=>setMode(mode==='policy'?'':'policy')}><ShieldCheck size={14}/>Break policies</button>}{data.manager&&scheduling&&<button className="btn btn-blue btn-small" onClick={()=>{setMode('shift');setEditShift(null);}}><Plus size={15}/>Create shifts</button>}</div></div>
  {error&&<div className="workspace-alert" role="alert">{error}</div>}{notice&&<div className="wf-success" role="status"><CheckCircle2 size={17}/>{notice}</div>}
  <form className="wf-filterbar" onSubmit={event=>{event.preventDefault();changeRange(dateDraft.from,dateDraft.to);}}>
    <label>From<input type="date" required max={dateDraft.to||undefined} value={dateDraft.from} onChange={event=>setDateDraft({...dateDraft,from:event.target.value})}/></label>
    <label>To<input type="date" required min={dateDraft.from||undefined} value={dateDraft.to} onChange={event=>setDateDraft({...dateDraft,to:event.target.value})}/></label>
    <label>Report grouping<select value={filters.period} onChange={event=>control('period',event.target.value)}><option value="day">Daily</option><option value="week">Weekly</option><option value="month">Monthly</option></select></label>
    <button className="btn btn-blue btn-small" type="submit">Apply dates</button>
    {data.canExportAttendance!==false&&<a className="btn btn-outline btn-small" href={'/api/workforce/export?'+query}><Download size={14}/>Export attendance</a>}
  </form>
  {loadingRange&&!error&&<p className="wf-loading" role="status">Loading attendance for the selected filters…</p>}
  {!loadingRange&&<>
  {data.truncated&&<div className="wf-warning">The detail list is limited. Narrow the dates to see every interval; report totals and exports include the full authorized range.</div>}
  <div className="wf-stats" aria-label="Selected attendance totals">{statistics.map(({label,value,summary,Icon})=><div key={label}>
    <span className="wf-metric-icon"><Icon size={16} aria-hidden="true"/></span><span>{label}</span><strong>{value}</strong><small>{summary}</small>
  </div>)}</div>
  {mode==='policy'&&<PolicyForm data={data} busy={busy} save={input=>action('policy-save',input)} close={()=>setMode('')}/>}
  {mode==='shift'&&<ShiftForm data={data} actor={actor} shift={editShift} busy={busy} save={input=>action(editShift?'shift-edit':'shift-create',input)} close={()=>{setMode('');setEditShift(null);}}/>}
  {mode==='manual'&&<IntervalForm data={data} actor={actor} busy={busy} save={input=>action('manual-entry',input)} close={()=>setMode('')}/>}
  {mode==='correction'&&selected&&<IntervalForm key={selected.id} data={data} actor={actor} entry={selected} busy={busy} save={input=>action('correction-request',input)} close={()=>setMode('')}/>}
  {mode==='history'&&selected&&<section className="wf-panel"><header><h3>Attendance history · {selected.name}</h3><button className="icon-button" onClick={()=>setMode('')} aria-label="Close history"><X size={18}/></button></header>{history?<EventList events={history} zone={actor.timeZone}/>:<p>Loading recorded history…</p>}</section>}
  {review&&<section className="wf-panel wf-review" key={review.id+review.action}><header><h3>{review.title}</h3><button className="icon-button" onClick={()=>setReview(null)} aria-label="Close review"><X size={18}/></button></header><form className="wf-form" onSubmit={e=>{e.preventDefault();const value=formValues(e);void action(review.action,{...value,id:review.id,revision:review.revision,acknowledge:value.acknowledge==='on'});}}>{review.choices&&<label>Decision<select name="decision">{review.choices.map(s=><option key={s}>{s}</option>)}</select></label>}{review.incidents?.length?<div className="wf-warning"><strong>Recorded compliance incident</strong>{review.incidents.map(s=><p key={s}>{s}</p>)}<label className="wf-check"><input name="acknowledge" type="checkbox"/>I have documented this incident and am approving only actual payable time. This does not erase the issue or deduct an untaken break.</label></div>:null}<label>Review note / reason<textarea name="note" required maxLength={1500}/></label><button className="btn btn-blue btn-small" disabled={busy}>Save recorded decision</button></form></section>}
  {attendance&&<>
   {section==='attendance'&&<section className={'wf-clock-card '+(active?'clocked-in':'')}><div><span className="section-kicker">YOUR ATTENDANCE CLOCK</span><h2>{pause?'Taking a break':active?'You are clocked in':'Ready for your workday'}</h2><p>{active?`${dateText(active.starts_at,true,actor.timeZone)} · ${active.shift_id?'Scheduled work':'Unscheduled work'}`:'Signing in to the website does not start your work clock or paid time.'}</p>{active&&<div className="wf-live-hours"><strong>{clock(elapsed)}</strong><span>gross · {hours(Math.max(0,elapsed-unpaid))} payable so far</span></div>}{data.policyError&&!active&&<p className="wf-warning">{data.policyError}</p>}</div><div className="wf-clock-controls">{!active?<form className="wf-form" onSubmit={e=>{e.preventDefault();void action('clock-in',formValues(e));}}><label>Work shift<select name="shift"><option value="">Unscheduled work</option>{data.currentShifts.map(s=><option key={s.id} value={s.id}>{s.title} · {dateText(s.starts_at,true,actor.timeZone)}</option>)}</select></label><label>Unscheduled work reason<input name="note" maxLength={500}/></label><button className="btn btn-blue" disabled={busy||!data.policy}><LogIn size={17}/>Clock in</button></form>:pause?<><div className="wf-break-running"><Coffee size={23}/><strong>{pause.label} · {pause.paid?'Paid':'Unpaid'}</strong><span>{clock(Math.max(0,Math.floor((tick-Date.parse(pause.starts_at))/1000)))}</span></div><button className="btn btn-blue" disabled={busy} onClick={()=>void action('break-end',{revision:active.revision})}>End break</button></>:<><form className="wf-form" onSubmit={e=>{e.preventDefault();const v=formValues(e);void action('break-start',{...v,revision:active.revision,restricted:v.restricted==='on'});}}><label>Break type<select name="kind">{active.policy.breaks.map(b=><option key={b.key} value={b.key}>{b.label} · {b.minutes} min · {b.paid||active.policy.restricted?'Paid':'Unpaid'}</option>)}</select></label><label className="wf-check"><input name="restricted" type="checkbox"/>Required to remain available / restricted activities (paid)</label><button className="btn btn-outline" disabled={busy}><Coffee size={17}/>Start break</button></form><button className="btn btn-blue" disabled={busy} onClick={()=>void action('clock-out',{revision:active.revision})}><LogOut size={17}/>Clock out</button></>}</div></section>}
   <section className="wf-panel"><header><div><h3>Attendance records</h3><p>Clock events are separate from login history and task timers.</p></div>{(data.manager||data.policy?.manualAllowed)&&<button className="btn btn-outline btn-small" onClick={()=>setMode('manual')}><Plus size={14}/>Manual work entry</button>}</header>{data.rows.length?<div className="table-scroll"><table className="wf-table"><thead><tr><th>Employee / work</th><th>Clock interval</th><th>Gross / breaks</th><th>Payable</th><th>Schedule indicators</th><th>Actions</th></tr></thead><tbody>{data.rows.map(r=><tr key={r.id}><td><strong>{r.name}</strong><small>{r.title??'Unscheduled work'} · {r.source}</small><small>{r.location}</small></td><td>{dateText(r.starts_at,true,r.time_zone)}<small>to {r.ends_at?dateText(r.ends_at,true,r.time_zone):'Clock running'}</small></td><td>{hours(r.totals.gross)}<small>{hours(r.totals.breakSeconds)} breaks · {hours(r.totals.unpaid)} unpaid</small></td><td><strong>{hours(r.totals.paid)}</strong><small>{r.timesheet_status??'Not yet submitted'}</small></td><td>{r.shift_start&&<small>Scheduled: {dateText(r.shift_start,true,r.time_zone)} to {dateText(r.shift_end,true,r.time_zone)}</small>}{r.late&&<Badge>{r.lateMinutes}m late</Badge>}{r.early&&<Badge>{r.earlyMinutes}m early</Badge>}{r.missedClockOut&&<Badge>Check missed clock-out</Badge>}{r.issues.map(s=><small className="wf-issue" key={s}>{s}</small>)}{!r.late&&!r.early&&!r.issues.length&&!r.missedClockOut&&<small>{r.shift_id?'Within schedule indicators':'Unscheduled'}</small>}</td><td><div className="wf-row-actions">{(r.employee_id===actor.id||data.policyAdmin)&&<button onClick={()=>{setSelected(r);setMode('correction');}}>Request correction</button>}<button onClick={()=>void showHistory(r)}>History</button></div>
   {data.staffReadiness&&actor.role==='super_admin'&&r.employee_id!==actor.id&&r.ends_at&&r.totals.paid<3*3600&&
    data.staff.find(e=>e.id===r.employee_id)?.jurisdiction==='CA-AB'&&<details><summary>Review reporting pay</summary>
    <ActionForm path="governance/reporting-review" extra={{attendance:r.id}} fields={[
      {name:"classification",label:"Reporting classification",options:[["Required","Required"],["Voluntary early departure","Voluntary early departure"],["Employee-requested short work","Employee-requested short work"]],required:true},
      {name:"reason",label:"Evidence for this decision",type:"textarea",required:true},
    ]} submit="Save reporting review" refresh={()=>void load().catch(e=>setError(e.message))}/></details>}</td></tr>)}</tbody></table></div>:<Empty text="No clock records exist for these dates. Your attendance starts only when you clock in."/>}</section>
   <Reports report={data.report}/><Absences data={data} actor={actor} review={setReview}/>
  </>}
  {scheduling&&<>
   <section className="wf-panel"><header><div><h3>{data.team?'Team schedule':'Your published schedule'}</h3><p>Work locations, time off and holidays in one calendar.</p></div><div className="wf-actions"><button className="icon-button" onClick={()=>navMonth(-1)} aria-label={calendar==='week'?'Previous week':'Previous month'}><ArrowLeft size={16}/></button><strong className="wf-schedule-range">{calendar==='week'?dateText(filters.from)+' – '+dateText(filters.to):new Intl.DateTimeFormat('en',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(filters.from+'T12:00Z'))}</strong><button className="icon-button" onClick={()=>navMonth(1)} aria-label={calendar==='week'?'Next week':'Next month'}><ArrowRight size={16}/></button><div className="wf-segment"><button className={calendar==='week'?'active':''} onClick={()=>{setCalendar('week');const first=dayAdd(filters.from,-((new Date(filters.from+'T12:00Z').getUTCDay()+6)%7));changeRange(first,dayAdd(first,6));}}>Weekly</button><button className={calendar==='month'?'active':''} onClick={()=>{setCalendar('month');const first=filters.from.slice(0,7)+'-01';changeRange(first,monthEnd(first));}}>Monthly</button></div></div></header><ScheduleCalendar data={data} mode={calendar} zone={actor.timeZone}/></section>
   <section className="wf-panel"><header><h3>Shift assignments</h3>{data.team&&data.manager&&<button className="btn btn-blue btn-small" disabled={busy||!checked.length} onClick={()=>void action('shift-publish',{ids:checked})}>Publish selected ({checked.length})</button>}</header>{data.shifts.length?<div className="table-scroll"><table className="wf-table"><thead><tr><th>{data.team&&<input type="checkbox" aria-label="Select up to 100 draft shifts" checked={!!checked.length&&checked.length===Math.min(100,data.shifts.filter(s=>s.state==='Draft').length)} onChange={e=>setChecked(e.target.checked?data.shifts.filter(s=>s.state==='Draft').slice(0,100).map(s=>s.id):[])}/>}</th><th>Shift / employee</th><th>Work time</th><th>Location</th><th>Status</th><th>Actions</th></tr></thead><tbody>{data.shifts.map(s=><tr key={s.id}><td>{data.team&&s.state==='Draft'&&<input type="checkbox" aria-label={'Select '+s.title+' for '+s.name} checked={checked.includes(s.id)} onChange={e=>setChecked(c=>e.target.checked?[...c,s.id]:c.filter(id=>id!==s.id))}/>}</td><td><strong>{s.title}</strong><small>{s.name}</small><small>{s.series_id?'Recurring assignment':'Single occurrence'}{s.group_key?' · Grouped occurrence':''}</small></td><td>{dateText(s.starts_at,true,s.time_zone)}<small>to {dateText(s.ends_at,true,s.time_zone)} · {s.time_zone}</small></td><td>{s.location}</td><td><Badge>{s.state}</Badge>{(s.leave_conflict>0||s.holiday_conflict>0)&&s.state!=='Cancelled'&&<small className="wf-issue">Time-off / holiday conflict: review schedule</small>}</td><td><div className="wf-row-actions">{data.manager&&data.team&&s.starts_at>data.serverTime&&s.state!=='Cancelled'&&<><button onClick={()=>{setEditShift(s);setMode('shift');}}>Edit</button><button onClick={()=>setReview({action:'shift-cancel',id:s.id,revision:s.revision,title:'Cancel upcoming shift'})}>Cancel</button></>}{s.employee_id===actor.id&&s.state==='Published'&&Date.parse(s.starts_at)>tick+86400000&&<button onClick={()=>setMode('swap:'+s.id)}>Request swap</button>}</div></td></tr>)}</tbody></table></div>:<Empty text="No shifts exist in this date range. Published schedules appear here after coordinator approval."/>}</section>
   {mode.startsWith('swap:')&&<section className="wf-panel"><header><h3>Request a shift swap</h3><button className="icon-button" onClick={()=>setMode('')} aria-label="Close swap"><X size={18}/></button></header><form className="wf-form" onSubmit={e=>{e.preventDefault();void action('swap-request',{...formValues(e),source:mode.slice(5)});}}><label>Colleague’s published shift<select name="target" required><option value="">Choose a shift</option>{data.swapChoices.map(s=><option key={s.id} value={s.id}>{s.name} · {s.title} · {dateText(s.starts_at,true,s.time_zone)}</option>)}</select></label><label>Reason<textarea name="note" required maxLength={1000}/></label><p>The other employee must accept, then an independent coordinator must approve. Shift availability and Alberta notice/rest limits are checked again at approval.</p><button className="btn btn-blue btn-small" disabled={busy||!data.swapChoices.length}>Send swap request</button></form></section>}
   <section className="wf-panel"><header><h3>Shift swap requests</h3></header>{data.swaps.length?<div className="wf-request-list">{data.swaps.map(s=><article key={s.id}><div><strong>{s.requester} ↔ {s.partner}</strong><p>{dateText(s.source_start,true,actor.timeZone)} ↔ {dateText(s.target_start,true,actor.timeZone)}</p><p>{s.note}</p>{s.review_note&&<small>Review: {s.review_note}</small>}<Badge>{s.status}</Badge></div><div className="wf-row-actions">{s.partner_id===actor.id&&s.status==='Awaiting employee'&&<><button disabled={busy} onClick={()=>void action('swap-response',{id:s.id,revision:s.revision,accept:true})}>Accept</button><button disabled={busy} onClick={()=>void action('swap-response',{id:s.id,revision:s.revision,accept:false})}>Decline</button></>}{s.requester_id===actor.id&&['Awaiting employee','Pending approval'].includes(s.status)&&<button disabled={busy} onClick={()=>void action('swap-cancel',{id:s.id,revision:s.revision})}>Cancel request</button>}{data.manager&&![s.requester_id,s.partner_id].includes(actor.id)&&s.status==='Pending approval'&&<button onClick={()=>setReview({action:'swap-review',id:s.id,revision:s.revision,title:'Review accepted shift swap',choices:['Approved','Declined']})}>Review</button>}</div></article>)}</div>:<Empty text="No shift-swap requests have been made."/>}</section>
   <Absences data={data} actor={actor} review={setReview}/>
  </>}
  {(sheets||section==='attendance')&&<>
   {sheets&&data.workExceptions&&<section className="wf-panel"><WorkExceptions rows={data.workExceptions} from={data.from} through={data.to} drillDown={false}/></section>}
   {sheets&&<section className="wf-panel"><header><div><h3>{data.team?'Team timesheet review':'Your timesheets'}</h3><p>Approved corrections recalculate and resubmit hours. You cannot approve your own hours.</p></div>{(data.manager||data.policy?.manualAllowed)&&<button className="btn btn-outline btn-small" onClick={()=>setMode('manual')}>Add authorized manual work</button>}</header>{data.sheets.length?<div className="table-scroll"><table className="wf-table"><thead><tr><th>Employee / day</th><th>Gross</th><th>Unpaid</th><th>Payable</th><th>Status / compliance</th><th>Actions</th></tr></thead><tbody>{data.sheets.map(s=>{const incidents=JSON.parse(s.compliance_issues) as string[];return <tr key={s.id}><td><strong>{s.name}</strong><small>{dateText(s.work_date)} · {s.source}</small></td><td>{hours(s.gross_seconds)}</td><td>{hours(s.unpaid_seconds)}</td><td><strong>{hours(s.paid_seconds)}</strong></td><td><Badge>{s.status}</Badge>{incidents.map(i=><small key={i} className="wf-issue">{i}</small>)}{s.review_note&&<small>Review: {s.review_note}</small>}</td><td>{s.employee_id===actor.id&&['Draft','Returned'].includes(s.status)?<button className="btn btn-outline btn-small" disabled={busy} onClick={()=>void action('timesheet-submit',{id:s.id,revision:s.revision})}>Submit hours</button>:data.manager&&s.employee_id!==actor.id&&s.status==='Submitted'?<button className="btn btn-outline btn-small" onClick={()=>setReview({action:'timesheet-review',id:s.id,revision:s.revision,title:'Review recorded hours for '+s.name,choices:['Approved','Returned'],incidents})}>Review</button>:<small>Recorded</small>}</td></tr>;})}</tbody></table></div>:<Empty text="Timesheets are created from a completed attendance interval or an authorized manual entry."/>}</section>}
   <section className="wf-panel"><header><h3>Attendance correction requests</h3></header>{data.corrections.length?<div className="wf-request-list">{data.corrections.map(c=><article key={c.id}><div><strong>{c.name}</strong><p>Proposed: {dateText(c.proposed_start,true,actor.timeZone)} → {dateText(c.proposed_end,true,actor.timeZone)}</p><p>{c.note}</p><details><summary>Proposed actual breaks</summary>{(JSON.parse(c.proposed_breaks) as WorkBreak[]).length?(JSON.parse(c.proposed_breaks) as WorkBreak[]).map((b,i)=><p key={i}>{b.kind} · {dateText(b.starts_at,true,actor.timeZone)} → {dateText(b.ends_at,true,actor.timeZone)} · {b.paid?'Paid':'Unpaid'}{b.restricted?' · Restricted activities':''}</p>):<p>No breaks recorded. Missing statutory rest stays flagged; it is not deducted.</p>}</details>{c.review_note&&<p>Review: {c.review_note}</p>}<Badge>{c.status}</Badge></div><div className="wf-row-actions">{(c.employee_id===actor.id||c.requested_by===actor.id)&&c.status==='Pending'&&<button disabled={busy} onClick={()=>void action('correction-cancel',{id:c.id,revision:c.revision})}>Cancel request</button>}{data.policyAdmin&&c.employee_id!==actor.id&&c.requested_by!==actor.id&&c.status==='Pending'&&<button onClick={()=>setReview({action:'correction-review',id:c.id,revision:c.revision,title:'Review attendance correction for '+c.name,choices:['Approved','Returned']})}>Review proposed correction</button>}</div></article>)}</div>:<Empty text="Requests for missed clock-outs or incorrect work intervals appear here with their review history."/>}</section>
  </>}
  {(section==='leave'||section==='holidays')&&<>
   {section==='leave'&&data.leaveError&&<div className="workspace-alert">{data.leaveError}</div>}
   {section==='leave'&&data.leaveBalances&&<section className="wf-panel"><h3>Your leave balances</h3><div className="table-scroll"><table className="wf-table"><thead><tr><th>Leave</th><th>Annual cycle</th><th>Accrued hours</th><th>Used hours</th><th>Pending hours</th><th>Available hours</th></tr></thead><tbody>{data.leaveBalances.balances.map(balance=><tr key={balance.code}><td>{balance.name} · {balance.paid?'Paid':'Unpaid'}</td><td>{balance.from} to {balance.to}</td><td>{(balance.entitlement/60).toFixed(2)}</td><td>{(balance.used/60).toFixed(2)}</td><td>{(balance.pending/60).toFixed(2)}</td><td>{(balance.available/60).toFixed(2)}</td></tr>)}</tbody></table></div></section>}
   {section==='leave'&&<section className="wf-panel"><header><h3>Time off and sick days</h3><div className="wf-actions"><button className="btn btn-blue btn-small" onClick={()=>setMode('leave-request')}>Request time off</button>{data.manager&&<button className="btn btn-outline btn-small" onClick={()=>setMode('leave-record')}>Record employee time off</button>}</div></header>{mode.startsWith('leave-')&&<form className="wf-form" onSubmit={e=>{e.preventDefault();void action(mode,formValues(e));}}><div className="wf-form-grid">{mode==='leave-record'&&<label>Employee<select name="employee" required>{data.staff.filter(s=>s.id!==actor.id).map(s=><option value={s.id} key={s.id}>{s.name}</option>)}</select></label>}<label>Category<select name="category">{data.leaveBalances?data.leaveBalances.balances.map(c=><option key={c.code} value={c.code}>{c.name}</option>):['Vacation','Sick leave','Personal leave','Other'].map(c=><option key={c}>{c}</option>)}</select></label><label>Starts<input name="startsOn" type="date" required/></label><label>Ends<input name="endsOn" type="date" required/></label></div><label>Note<textarea name="note" maxLength={1000}/></label><button className="btn btn-blue btn-small" disabled={busy}>{mode==='leave-record'?'Record time off':'Submit request'}</button></form>}{data.leave.length?<div className="wf-request-list">{data.leave.map(l=><article key={l.id}><div><strong>{l.name} · {l.category}</strong><p>{dateText(l.starts_on)} to {dateText(l.ends_on)}</p><p>{l.note}</p><Badge>{l.status}</Badge>{l.review_note&&<small>Review: {l.review_note}</small>}</div><div className="wf-row-actions">{data.manager&&l.employee_id!==actor.id&&l.status==='Pending'&&<button onClick={()=>setReview({action:'leave-review',id:l.id,revision:l.revision,title:'Review time off for '+l.name,choices:['Approved','Declined']})}>Review</button>}{['Pending','Approved'].includes(l.status)&&<button onClick={()=>setReview({action:'leave-cancel',id:l.id,revision:l.revision,title:'Cancel time-off record'})}>Cancel</button>}</div></article>)}</div>:<Empty text="No time-off records overlap these dates."/>}</section>}
   <section className="wf-panel"><header><h3>Applicable holiday calendar</h3>{data.holidayManagement&&<a className="btn btn-outline btn-small" href="/staff/holiday-calendar">Holidays &amp; compliance</a>}{data.policyAdmin&&!data.holidayManagement&&<button className="btn btn-outline btn-small" onClick={()=>setMode(mode==='holiday'?'':'holiday')}>Record holiday</button>}</header>{mode==='holiday'&&<form className="wf-form" onSubmit={e=>{e.preventDefault();void action('holiday-create',formValues(e));}}><div className="wf-form-grid"><label>Holiday name<input name="name" required maxLength={100}/></label><label>Date<input name="day" type="date" required/></label><label>Type<select name="type"><option>Statutory</option><option>Company</option></select></label></div><p>Record applicable dates verified by your administrator. Holiday-pay calculations belong to payroll; this calendar records non-working dates.</p><button className="btn btn-blue btn-small" disabled={busy}>Save holiday</button></form>}{data.holidays.length?<div className="wf-request-list">{data.holidays.map(h=><article key={h.id}><div><strong>{h.name}</strong><p>{dateText(h.on_date)} · {h.type}</p>{h.cancelled_at&&<Badge>Cancelled</Badge>}</div>{data.policyAdmin&&!data.holidayManagement&&!h.cancelled_at&&<button className="btn btn-outline btn-small" onClick={()=>setReview({action:'holiday-cancel',id:h.id,title:'Cancel holiday calendar record'})}>Cancel</button>}</article>)}</div>:<Empty text="No holiday dates have been recorded in this range."/>}</section>
  </>}
  <details className="wf-panel wf-history"><summary>Recorded workforce activity</summary><EventList events={data.events} zone={actor.timeZone}/></details>
  <p className="wf-legal"><ShieldCheck size={15}/>Alberta standard adult-employee policies · <a href={data.rules.source} target="_blank" rel="noreferrer">Official hours and rest requirements</a> · Checked {data.rules.verifiedOn}. Actual pay records retain compliance incidents. Payroll rates, overtime and statutory holiday pay are handled separately.</p>
  </>}
 </div>;
}
function EventList({events,zone}:{events:Event[];zone:string}){return events.length?<div className="wf-events">{events.map(e=><article key={e.id}><Clock3 size={15}/><div><strong>{e.action}</strong><small>{e.name} · {e.actor??'Scheduled maintenance'} · {dateText(e.created_at,true,zone)}</small><details><summary>Recorded details</summary><pre>{(()=>{try{return JSON.stringify(JSON.parse(e.detail),null,2);}catch{return e.detail;}})()}</pre></details></div></article>)}</div>:<p className="wf-muted">No recorded activity in this view.</p>;}
function Reports({report}:{report:Report}){const [page,setPage]=useState(1),pages=Math.max(1,Math.ceil(report.rows.length/100));useEffect(()=>setPage(1),[report.from,report.to,report.period]);return <section className="wf-panel"><header><div><h3>Attendance report · {report.period==='day'?'Daily':report.period==='week'?'Weekly':'Monthly'}</h3><p>Overnight work is divided at the recorded work time zone’s local midnight. Open clocks are provisional.</p></div><FileCheck2 size={22}/></header>{report.rows.length?<div className="table-scroll"><table className="wf-table"><thead><tr><th>Employee</th><th>Period</th><th>Gross</th><th>Unpaid</th><th>Recorded payable</th><th>Approved</th><th>Open intervals</th></tr></thead><tbody>{report.rows.slice((Math.min(page,pages)-1)*100,Math.min(page,pages)*100).map(r=><tr key={r.employeeId+r.period}><td>{r.employee}<small>{r.employeeNo}</small></td><td>{r.period}</td><td>{hours(r.gross)}</td><td>{hours(r.unpaid)}</td><td>{hours(r.paid)}</td><td>{hours(r.approved)}</td><td>{r.openRecords}</td></tr>)}</tbody></table></div>:<Empty text="Attendance reports fill from real work intervals recorded during the selected dates."/>}{pages>1&&<div className="wf-report-pages"><button className="btn btn-outline btn-small" disabled={page<=1} onClick={()=>setPage(p=>p-1)}>Previous</button><span>Page {Math.min(page,pages)} of {pages} · {report.rows.length} rows</span><button className="btn btn-outline btn-small" disabled={page>=pages} onClick={()=>setPage(p=>p+1)}>Next</button></div>}</section>;}
function Absences({data,actor,review}:{data:Data;actor:Viewer;review:(v:Review)=>void}){return <section className="wf-panel"><header><div><h3>Scheduled attendance and absences</h3><p>Ended shifts are checked every five minutes. Leave, sickness and holidays remain distinct from unexcused no-shows.</p></div></header>{data.absences.length?<div className="table-scroll"><table className="wf-table"><thead><tr><th>Employee</th><th>Scheduled work</th><th>Outcome</th><th>Notes</th><th>Action</th></tr></thead><tbody>{data.absences.map(a=><tr key={a.id}><td>{a.name}</td><td>{a.title}<small>{dateText(a.starts_at,true,actor.timeZone)} to {dateText(a.ends_at,true,actor.timeZone)}</small></td><td><Badge>{a.status}</Badge></td><td>{a.note}</td><td>{data.manager&&a.employee_id!==actor.id&&a.status==='No show'&&<button className="btn btn-outline btn-small" onClick={()=>review({action:'absence-excuse',id:a.id,title:'Record an absence explanation'})}>Record excuse</button>}</td></tr>)}</tbody></table></div>:<Empty text="No ended scheduled shifts have absence outcomes in this view."/>}</section>;}
function ScheduleCalendar({data,mode,zone}:{data:Data;mode:string;zone:string}){const first=data.from.slice(0,7)+'-01',offset=(new Date((mode==='week'?data.from:first)+'T12:00Z').getUTCDay()+6)%7,start=dayAdd(mode==='week'?data.from:first,-offset),days=Array.from({length:mode==='week'?7:42},(_,i)=>dayAdd(start,i));return <div className={'wf-calendar '+(mode==='week'?'weekly':'')}><div className="wf-calendar-weekdays">{['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=><strong key={d}>{d}</strong>)}</div><div className="wf-calendar-days">{days.map(day=><div key={day} className={(day===data.today?'today ':'')+(day.slice(0,7)!==first.slice(0,7)?'outside':'')}><strong>{Number(day.slice(-2))}</strong>{data.shifts.filter(s=>s.state!=='Cancelled'&&wall(s.starts_at,zone).slice(0,10)===day).map(s=><article className={s.state==='Draft'?'draft':''} key={s.id}><strong>{s.title}</strong><span>{s.name}</span><span>{wall(s.starts_at,zone).slice(11)}–{wall(s.ends_at,zone).slice(11)}</span><small>{s.location} · {s.state}</small></article>)}{data.leave.filter(l=>l.status==='Approved'&&l.starts_on<=day&&l.ends_on>=day).map(l=><article className="time-off" key={l.id}>{l.name} · {l.category}</article>)}{data.holidays.filter(h=>!h.cancelled_at&&h.on_date===day).map(h=><article className="holiday" key={h.id}>{h.name}</article>)}</div>)}</div><p className="wf-muted">Calendar displayed in {zone}. Shift details retain their assigned time zone.</p></div>;}
function ShiftForm({data,actor,shift,busy,save,close}:{data:Data;actor:Viewer;shift:Scheduled|null;busy:boolean;save:(d:Record<string,unknown>)=>Promise<unknown>;close:()=>void}){
 const [recurring,setRecurring]=useState(false),[people,setPeople]=useState<string[]>(shift?[shift.employee_id]:[]),[weekdays,setWeekdays]=useState([1,2,3,4,5]);
 return <section className="wf-panel wf-editor"><header><div><h3>{shift?'Change upcoming shift':'Build the staff schedule'}</h3><p>Draft first, then publish. Times use the selected IANA time zone.</p></div><button className="icon-button" onClick={close} aria-label="Close shift editor"><X size={18}/></button></header><form className="wf-form" onSubmit={e=>{e.preventDefault();void save({...formValues(e),id:shift?.id,revision:shift?.revision,employees:people,recurring,weekdays});}}><div className="wf-form-grid"><label>Shift title<input name="title" required maxLength={100} defaultValue={shift?.title}/></label><label>Work location<input name="location" required maxLength={180} defaultValue={shift?.location}/></label><label>Starts (local)<input name="startsLocal" type="datetime-local" required defaultValue={shift?wall(shift.starts_at,shift.time_zone):dayAdd(data.today,1)+'T09:00'}/></label><label>Ends (local)<input name="endsLocal" type="datetime-local" required defaultValue={shift?wall(shift.ends_at,shift.time_zone):dayAdd(data.today,1)+'T17:00'}/></label><label>Shift time zone<input name="timeZone" required defaultValue={shift?.time_zone??actor.timeZone}/></label><label>Repeated daylight-saving hour<select name="fold"><option value="earlier">First occurrence</option><option value="later">Second occurrence</option></select></label>{shift?<label>Assigned employee<input readOnly value={shift.name}/></label>:<label className="wide">Assigned employees<select multiple required value={people} onChange={e=>setPeople(Array.from(e.target.selectedOptions,o=>o.value))}>{data.staff.map(s=><option value={s.id} key={s.id} disabled={!s.policy}>{s.name}{!s.policy?' · Alberta jurisdiction not set':''}</option>)}</select><small>Select multiple employees using Ctrl / Command. Each occurrence has a shared group reference.</small></label>}</div>{!shift&&<><label className="wf-check"><input type="checkbox" checked={recurring} onChange={e=>setRecurring(e.target.checked)}/>Repeat this shift</label>{recurring&&<div className="wf-recurring"><div className="wf-form-grid"><label>Repeat every (weeks)<input name="everyWeeks" type="number" defaultValue={1} min={1} max={4} required/></label><label>Through date<input name="until" type="date" required/></label></div><div className="wf-weekday-options">{['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((day,i)=><label key={day}><input type="checkbox" checked={weekdays.includes(i)} onChange={e=>setWeekdays(v=>e.target.checked?[...v,i]:v.filter(d=>d!==i))}/>{day}</label>)}</div><p>Up to 180 days and 500 employee assignments per request. Recurrence follows local clock time through daylight-saving changes; nonexistent times are rejected.</p></div>}</>}{shift&&<label>Reason for change<textarea name="note" required maxLength={1000}/></label>}<p>Alberta standard limits: twelve-hour shift span, eight hours between published shifts, one day off in seven, and at least twenty-four hours’ notice when changing a published shift.</p><button className="btn btn-blue btn-small" disabled={busy||!shift&&!people.length}>{shift?'Save shift changes':'Create draft assignments'}</button></form></section>;
}
type BreakInput={kind:string;startsLocal:string;endsLocal:string;restricted:boolean};
function IntervalForm({data,actor,entry,busy,save,close}:{data:Data;actor:Viewer;entry?:Entry;busy:boolean;save:(d:Record<string,unknown>)=>Promise<unknown>;close:()=>void}){
 const [employee,setEmployee]=useState(entry?.employee_id??actor.id),person=data.staff.find(s=>s.id===employee),timeZone=entry?.time_zone??person?.time_zone??actor.timeZone,policy=entry?JSON.parse(entry.policy_snapshot) as WorkPolicy:person?.policy??data.policy;
 const [breaks,setBreaks]=useState<BreakInput[]>(entry?.breaks.filter(b=>b.ends_at).map(b=>({kind:b.kind,startsLocal:wall(b.starts_at,timeZone),endsLocal:wall(b.ends_at!,timeZone),restricted:!!b.restricted}))??[]);
 function change(i:number,key:string,v:string|boolean){setBreaks(b=>b.map((r,index)=>index===i?{...r,[key]:v}:r));}
 return <section className="wf-panel wf-editor"><header><div><h3>{entry?'Request an attendance correction':'Record actual manual work'}</h3><p>{entry?'Proposed changes require an independent administrator. Original work stays unchanged until approval.':'Manual-entry authorization is checked on the server. Hours go to independent review.'}</p></div><button className="icon-button" onClick={close} aria-label="Close work interval editor"><X size={18}/></button></header><form className="wf-form" onSubmit={e=>{e.preventDefault();void save({...formValues(e),employee,id:entry?.id,revision:entry?.revision,breaks});}}><div className="wf-form-grid">{data.manager&&!entry&&<label>Employee<select value={employee} onChange={e=>{setEmployee(e.target.value);setBreaks([]);}}>{data.staff.map(s=><option key={s.id} value={s.id} disabled={!s.policy}>{s.name}</option>)}</select></label>}<label>Recorded time zone<input readOnly value={timeZone}/></label><label>Actual start (local)<input name="startsLocal" type="datetime-local" required defaultValue={entry?wall(entry.starts_at,timeZone):data.today+'T09:00'}/></label><label>Actual end (local)<input name="endsLocal" type="datetime-local" required defaultValue={entry?.ends_at?wall(entry.ends_at,timeZone):wall(data.serverTime,timeZone)}/></label><label>Repeated daylight-saving hour<select name="fold"><option value="earlier">First occurrence</option><option value="later">Second occurrence</option></select></label>{!entry&&<label>Related scheduled shift<select name="shift"><option value="">Unscheduled work</option>{data.shifts.filter(s=>s.employee_id===employee&&s.state==='Published').map(s=><option key={s.id} value={s.id}>{s.title} · {dateText(s.starts_at,true,s.time_zone)}</option>)}</select></label>}</div><h4>Actual breaks taken</h4><p>Include each real break with its start and end. Paid status comes from the recorded policy; restricted activities make a break paid.</p>{breaks.map((b,i)=><div className="wf-break-input" key={i}><label>Break type<select required value={b.kind} onChange={e=>change(i,'kind',e.target.value)}>{policy?.breaks.map(option=><option key={option.key} value={option.key}>{option.label} · {option.paid?'Paid':'Unpaid'}</option>)}</select></label><label>Actual start<input type="datetime-local" required value={b.startsLocal} onChange={e=>change(i,'startsLocal',e.target.value)}/></label><label>Actual end<input type="datetime-local" required value={b.endsLocal} onChange={e=>change(i,'endsLocal',e.target.value)}/></label><label className="wf-check"><input type="checkbox" checked={b.restricted} onChange={e=>change(i,'restricted',e.target.checked)}/>Restricted / available</label><button className="icon-button" type="button" aria-label="Remove proposed break" onClick={()=>setBreaks(v=>v.filter((_,index)=>index!==i))}><X size={16}/></button></div>)}<button className="btn btn-outline btn-small" type="button" disabled={!policy} onClick={()=>setBreaks(v=>[...v,{kind:policy?.breaks[0]?.key??'',startsLocal:'',endsLocal:'',restricted:false}])}><Plus size={14}/>Add actual break</button><label>Reason / work note<textarea name="note" required maxLength={1500}/></label><button className="btn btn-blue btn-small" disabled={busy||!policy}>{entry?'Send correction for approval':'Submit manual work for review'}</button></form></section>;
}
function PolicyForm({data,busy,save,close}:{data:Data;busy:boolean;save:(d:Record<string,unknown>)=>Promise<unknown>;close:()=>void}){
 const [effectiveOn,setEffectiveOn]=useState(data.today);
 const [employee,setEmployee]=useState(data.staff.find(s=>s.policy)?.id??''),person=data.staff.find(s=>s.id===employee),[policy,setPolicy]=useState(person?.policy??null);
 function pickEmployee(id:string){setEmployee(id);setPolicy(data.staff.find(s=>s.id===id)?.policy??null);}
 function updateBreak(i:number,key:string,value:string|number|boolean){setPolicy(p=>p?{...p,breaks:p.breaks.map((b,index)=>index===i?{...b,[key]:value}:b)}:p);}
 return <section className="wf-panel wf-editor"><header><div><h3>Employee break and time-entry policy</h3><p>Policies may improve the statutory minimum. They cannot reduce it.</p></div><button className="icon-button" onClick={close} aria-label="Close policy editor"><X size={18}/></button></header><label className="wf-label">Employee<select value={employee} onChange={e=>pickEmployee(e.target.value)}><option value="">Choose employee</option>{data.staff.map(s=><option key={s.id} value={s.id}>{s.name} · {s.jurisdiction||'Employment jurisdiction missing'}</option>)}</select></label>{!policy?<p className="wf-warning">Set this employee’s employment jurisdiction to CA-AB in their employee profile before configuring Alberta work rules.</p>:<form className="wf-form" onSubmit={e=>{e.preventDefault();void save({employee,revision:person?.policyRevision??0,policy,effectiveOn});}}>{policy.breaks.map((b,i)=><div className="wf-break-input policy" key={b.key}><label>Break label<input value={b.label} required maxLength={80} onChange={e=>updateBreak(i,'label',e.target.value)}/></label><label>Duration (minutes)<input type="number" min={1} max={120} required value={b.minutes} onChange={e=>updateBreak(i,'minutes',Number(e.target.value))}/></label><label>Planned offset (minutes)<input type="number" min={0} max={720} required value={b.afterMinutes} onChange={e=>updateBreak(i,'afterMinutes',Number(e.target.value))}/></label><label className="wf-check"><input type="checkbox" checked={b.paid} onChange={e=>updateBreak(i,'paid',e.target.checked)}/>Paid break</label><button className="icon-button" type="button" aria-label={'Remove '+b.label} onClick={()=>setPolicy(p=>p?{...p,breaks:p.breaks.filter((_,index)=>index!==i)}:p)}><X size={16}/></button></div>)}<button type="button" className="btn btn-outline btn-small" onClick={()=>setPolicy(p=>p?{...p,breaks:[...p.breaks,{key:'break-'+Date.now().toString(36),label:'',minutes:15,paid:true,afterMinutes:120}]}:p)}><Plus size={14}/>Add custom break type</button><p>Paid 15-minute rests, paid/unpaid 30-minute lunches, unpaid 60-minute lunches and custom durations are supported alongside the statutory rests. Breaks may occur multiple times. Short shifts place necessary rests early enough to finish before the shift ends.</p><label className="wf-check"><input type="checkbox" checked={policy.splitAgreement} onChange={e=>setPolicy({...policy,splitAgreement:e.target.checked})}/>Written agreement permits splitting each required 30-minute rest into two 15-minute rests.</label>{policy.splitAgreement&&<label>Written split-break agreement reference<input required minLength={8} maxLength={600} value={policy.splitAgreementReference??''} onChange={e=>setPolicy({...policy,splitAgreementReference:e.target.value})}/></label>}<label className="wf-check"><input type="checkbox" checked={policy.restricted} onChange={e=>setPolicy({...policy,restricted:e.target.checked})}/>Break activities are restricted / employee must remain available: all breaks must be paid.</label><label className="wf-check"><input type="checkbox" checked={policy.manualAllowed} onChange={e=>setPolicy({...policy,manualAllowed:e.target.checked})}/>Authorize this employee to submit manual time entries.</label><div className="wf-form-grid"><label>Late indicator grace (minutes)<input type="number" min={0} max={60} value={policy.lateGrace} onChange={e=>setPolicy({...policy,lateGrace:Number(e.target.value)})}/></label><label>Early indicator grace (minutes)<input type="number" min={0} max={60} value={policy.earlyGrace} onChange={e=>setPolicy({...policy,earlyGrace:Number(e.target.value)})}/></label></div>{data.staffReadiness&&<><label className="wf-label">Effective on<input type="date" value={effectiveOn} onChange={event=>setEffectiveOn(event.target.value)} required/></label>
  {Boolean(person?.policyVersions?.length)&&<p>Saved versions: {person?.policyVersions?.map(v=>v.effective+' (v'+v.revision+')').join(', ')}</p>}</>}<p>Indicator grace does not change recorded hours. Actual unpaid break intervals determine the deduction. Existing attendance retains its policy snapshot and immutable change history.</p><button className="btn btn-blue btn-small" disabled={busy}>Save employee policy</button></form>}</section>;
}
